-- 051_storesync.sql
-- Ny partner: StoreSync (tidligere Storebuddy), Marius Bugge, 7. okt. 2026.
-- Firma: Shine Solutions ApS, CVR 33239106 (StoreSync er købt af Shine; bekræftet af Marius).
INSERT INTO partner (id, slug, status, vist_i_spil, navn, firmanavn, cvr, adresse, hjemmeside,
                     kort_beskrivelse, produktkategori, privatlivspolitik, afmeld_email,
                     kontakt_navn, kontakt_email, levering_navn, levering_email,
                     giver_praemie, praemie_titel, praemie_beskrivelse, praemie_vaerdi, praemie_vaerdi_type, praemie_moms,
                     praemie_betingelser, praemie_indloesning, praemie_sidste_frist, praemie_flyt,
                     fordel_rabat, fordel_ydelse, fordel_koebskrav, logo, logo_type)
SELECT gen_random_uuid(), 'storesync', 'aktiv', true, 'StoreSync', 'Shine Solutions ApS', '33239106',
       'Fiolstræde 17B, 1171 København K', 'https://storebuddy.io/da',
       'StoreSync automatiserer bogføring, fakturering og moms mellem webshop og regnskabssystem (e-conomic, Dinero, Shine Regnskab m.fl.).',
       'automatisk bogføring, fakturering og moms mellem webshop og regnskabssystem',
       'https://storebuddy.io/da/legal/privacy', 'marius@storebuddy.dk',
       'Marius Bugge', 'marius@storebuddy.dk', 'Marius Bugge', 'marius@storebuddy.dk',
       true, '6 måneders gratis StoreSync',
       'Vinderfirmaet får 6 måneders gratis StoreSync, der automatiserer bogføring, fakturering og moms mellem webshop og regnskabssystem. Vinderen får den plan, der passer til deres webshop.',
       24606, 'op_til', 'ekskl',
       'Op til 24.606 kr. ekskl. moms. Værdien afhænger af ordrevolumen.',
       'Vinderen skriver til Marius Bugge på marius@storebuddy.dk.',
       DATE '2027-03-31', 'nej',
       '20 % rabat', 'på 6 måneders StoreSync',
       'Gælder nye kunder, der sætter flueben ved StoreSync, når de tilmelder sig i spillet.',
       decode('', 'base64'), 'image/png'
WHERE NOT EXISTS (SELECT 1 FROM partner p WHERE p.slug = 'storesync')
  AND EXISTS (SELECT 1 FROM partner z WHERE lower(z.navn) = 'zignifikant');
